function makeStarterWeapon(classId){
 // config_items first: lowest-ilvl COMMON/tier-1 weapon of the class's own
 // weapon category - the starter weapon must always be tier 1 of the
 // class's weapon type, never a higher-tier item even if that's all that's
 // configured for the category (falls through to the guaranteed tier-1
 // manually-built weapon below instead).
 const weapons=configItems.filter(r=>((r.item_json||r).slot||r.slot)==='weapon');
 // an advanced/custom class can pin an explicit starter weapon TYPE in its
 // editor (class_json.starterWeaponType) - translate that to the same
 // "category" bucket the generic classStarterWeaponCategories table uses,
 // so both paths share the rest of this lookup unchanged.
 const starterType=configClassRowForId(classId)?.class_json?.starterWeaponType;
 const explicitCat=starterType?configWeaponTypeCategories[starterType]:'';
 if(weapons.length){
  const cat=explicitCat||classStarterWeaponCategories[classId]||'';
  let cands=weapons.filter(r=>{const it=r.item_json||r;return (it.weaponCategory||'')===cat&&(it.rarity||r.tier||'common')==='common'});
  if(cands.length){
   cands=[...cands].sort((a,b)=>(Number((a.item_json||a).itemLevel||a.ilvl)||1)-(Number((b.item_json||b).itemLevel||b.ilvl)||1));
   const item=configuredItemFromRow(cands[0],{itemLevel:{min:1,max:2}},1);
   if(item){item.name=`${item.name} de aprendiz`;return item}
  }
 }
 const category=explicitCat||classStarterWeaponCategories[classId]||'Espadas básicas y elementales';
 const row=weaponRowForCategory(category),col=0,canonicalCategory=weaponRows[row].category;
 const stat=weaponCategoryStats[canonicalCategory]||'strength';
 const statLabel=DEFENSE_STAT_LABELS[stat]||'Fuerza';
 return{
  id:crypto.randomUUID(),slot:'weapon',iconShape:'blade',rarity:'common',label:'Común',itemLevel:1,score:8,
  name:`${weaponNameForCategory(canonicalCategory,col)} de aprendiz`,
  theme:'starter',weaponCategory:canonicalCategory,weaponIconRow:row,weaponIconCol:col,weaponIconPath:weaponIconPath(row,col),
  flavor:`Arma inicial de clase: ${canonicalCategory}. Icono básico individual por tipo de arma.`,
  defenseStat:stat,
  affixes:[{key:stat,label:statLabel,value:1,percent:false}],passives:[],effects:[],
  desc:'Nivel 1 · Poder 8'
 };
}

function normalizeConfiguredPotion(item,row={}){if(!isConfiguredPotionRow({...row,item_json:item}))return item;item.type='potion';item.slot='consumable';item.iconShape=item.iconShape||'vial';item.effects=Array.isArray(item.effects)?item.effects:[];item.range=Number(item.range)||0;item.desc=item.desc||describePotionEffects(item);return item}
function configWeaponKind(item){
 const text=`${item.weaponType||''} ${item.weaponCategory||''} ${item.name||item.nombre||''}`.toLowerCase();
 if(/varita/.test(text))return 'magic';
 if(/arco|ballesta|pistola|rifle|fusil|carabina|escopeta/.test(text)||(Number(item.rangeMax)||1)>1)return 'ranged';
 return 'melee';
}
function makeConfiguredLoot(level,minRarityName=null){if(!configItems.length)return null;const lootRow=currentLootProgressionRow(game?.floor||1,game?.player?.level||level||1);let eligible=configItems.filter(row=>lootRarityAllowed((row.item_json||row).rarity||row.tier||'common',lootRow));if(!eligible.length)return null;
 // Same guaranteed-minimum reasoning as weightedRarity()'s minRarityName -
 // falls back to the unrestricted eligible pool if nothing configured meets
 // the minimum, rather than returning no item at all.
 if(minRarityName){
  const minIdx=LOOT_RARITY_ORDER.indexOf(minRarityName);
  const above=eligible.filter(row=>LOOT_RARITY_ORDER.indexOf((row.item_json||row).rarity||row.tier||'common')>=minIdx);
  if(above.length)eligible=above;
 }
 // prefer items whose base ilvl fits the floor's loot band
 const inBand=eligible.filter(r=>{const il=Number((r.item_json||r).itemLevel||r.ilvl)||1;return il>=lootRow.itemLevel.min-3&&il<=lootRow.itemLevel.max+3});
 const row=pick(inBand.length?inBand:eligible);
 return configuredItemFromRow(row,lootRow,level)}
function configuredItemFromRow(row,lootRow,level){const raw=row.item_json||row,item={...raw};item.id=crypto.randomUUID();item.name=item.name||row.nombre||'Objeto configurado';item.slot=item.slot||row.slot||'trinket1';item.rarity=item.rarity||row.tier||'common';item.label=item.label||tierDefs[item.rarity]?.label||item.rarity;item.itemLevel=Math.max(lootRow.itemLevel.min,Math.min(lootRow.itemLevel.max,Number(item.itemLevel||row.ilvl||level||1)));item.score=Number(item.score||item.itemLevel*8);item.icon=item.icon||row.icon||'';item.damageDice=item.slot==='weapon'?(item.damageDice||row.damageDice||'1d6'):null;if(item.slot==='weapon'){item.weaponType=item.weaponType||row.weaponType||row.weaponCategory||'Sin tipo de arma';item.weaponCategory=item.weaponCategory||configWeaponTypeCategories[item.weaponType]||row.weaponCategory||weaponCategories[0];item.weaponIconRow=Number.isInteger(item.weaponIconRow)?item.weaponIconRow:weaponRowForCategory(item.weaponCategory);item.weaponIconCol=Number.isInteger(item.weaponIconCol)?item.weaponIconCol:weaponPowerColumn(item.itemLevel,item.rarity,item.score);item.weaponIconPath=item.weaponIconPath||weaponIconPath(item.weaponIconRow,item.weaponIconCol);item.defenseStat=item.defenseStat||WEAPON_TYPE_STAT[item.weaponType]||weaponCategoryStats[item.weaponCategory]||'strength';const bounds=weaponRangeBounds(item);item.rangeMin=bounds.min;item.rangeMax=bounds.max}normalizeConfiguredPotion(item,row);item.skillIds=Array.isArray(item.skillIds)?item.skillIds:[];item.affixes=Array.isArray(item.affixes)?item.affixes:parseConfigStats(row.stats||item.stats);item.passives=item.passives||[];item.effects=item.effects||[];if(EQUIPMENT_ACTIVE_SLOTS.has(item.slot)&&item.effects.length)item.cooldown=Math.max(1,Number(item.cooldown)||1);item.desc=item.desc||`Configurado · Nivel ${item.itemLevel} · Poder ${item.score}`;item.flavor=item.flavor||'Objeto creado en modo configuración.';return applyOffhandGuarantee(item)}
function parseConfigStats(text){return String(text||'').split(/[\n,;]/).map(x=>x.trim()).filter(Boolean).map(part=>{const m=part.match(/^([^:+-]+)\s*:?\s*([+-]?\d+)/);return m?{key:m[1].trim(),label:m[1].trim(),value:Number(m[2]),percent:false}:null}).filter(Boolean)}
function tierColor(tier){return tierDefs[tier]?.color||'#ddd'}
const configImageCache={};function configIconImage(src){if(!configImageCache[src]){const img=new Image();img.src=src;configImageCache[src]=img}return configImageCache[src]}
function hexToBase64(hex){const bytes=hex.match(/.{1,2}/g)||[];let bin='';bytes.forEach(b=>bin+=String.fromCharCode(parseInt(b,16)));return btoa(bin)}
// Itemization uses config_items exclusively; the random generator below only
// remains as a fallback for when the table is empty or has no eligible rows.
function makeLoot(level,source='normal',forceRarityName=null,forceKind=null,minRarityName=null){const lootRow=currentLootProgressionRow(game?.floor||1,game?.player?.level||level||1);if(forceKind==='potion')return makePotion(encounterLootQuality(source));if(forceKind!=='equipment'&&!forceRarityName&&Math.random()<Math.min(.22,.07+game.floor*.025+(source==='boss'? .08:0))){const potion=makePotion(encounterLootQuality(source));if(potion)return potion}
 if(forceRarityName){
  // Used only by the guaranteed floor-completion reward (grantFloorRewardPopup):
  // it must always be real equipment, never a configured potion (which could
  // also just teach a skill via its learnSkill effect) - so configured
  // potions are excluded from the pool even if their rarity matches.
  if(configItems.length){
   const matches=configItems.filter(row=>{
    const j=row.item_json||row;
    return (j.rarity||row.tier||'common')===forceRarityName&&j.type!=='potion';
   });
   if(matches.length)return configuredItemFromRow(pick(matches),lootRow,level);
  }
 } else {
  const configured=makeConfiguredLoot(level,minRarityName);if(configured)return configured;
 }
 const slot=pick(slots),rar=forceRarityName?(rarities.find(r=>r.name===forceRarityName)||weightedRarity(level,minRarityName)):weightedRarity(level,minRarityName);
 const itemLevel=Math.max(lootRow.itemLevel.min,Math.min(lootRow.itemLevel.max,level+rng(3)-1));
 const affixes=buildItemAffixes(slot,itemLevel,rar),passives=buildPassives(itemLevel,rar),effects=buildEffects(rar);
 const score=itemBudget(itemLevel,rar)+affixes.reduce((s,a)=>s+a.value,0)+passives.length*12+effects.length*25;
 const iconShape=pick(itemIconShapes[slot]),themed=pickThemedItem(slot);
 const weaponCategory=slot==='weapon'?weaponCategoryForLoot(rar):null;
 const weaponIconRow=weaponCategory?weaponRowForCategory(weaponCategory):null;
 const weaponIconCol=weaponCategory?weaponPowerColumn(itemLevel,rar,score):null;
 const weaponIconPathValue=weaponCategory?weaponIconPath(weaponIconRow,weaponIconCol):null;
 const armorIconRow=slot==='chest'?armorRowForLoot(rar):null;
 const armorIconCol=slot==='chest'?armorPowerColumn(itemLevel,rar,score):null;
 const armorIconPathValue=slot==='chest'?armorIconPath(armorIconRow,armorIconCol):null;
 // Offhand loot rolls one of 3 kinds - mostly shields, sometimes a wand or a
 // dagger held in the left hand alongside the main-hand weapon.
 const offhandKind=slot==='offhand'?pick(['shield','shield','shield','wand','dagger']):null;
 const offhandNameCategory=offhandKind==='wand'?configWeaponTypeCategories.Varitas:offhandKind==='dagger'?configWeaponTypeCategories.Dagas:null;
 const offhandName=offhandNameCategory?weaponNameForCategory(offhandNameCategory,weaponPowerColumn(itemLevel,rar,score)):null;
 return applyOffhandGuarantee({
  id:crypto.randomUUID(),slot,iconShape,rarity:rar.name,label:rar.label,itemLevel,score,
  name:slot==='weapon'?weaponNameForCategory(weaponCategory,weaponIconCol):slot==='chest'?armorName(armorIconRow,armorIconCol):(offhandName||themed?.name||`${pick(itemBases[slot])} ${pick(prefixes)}`),
  theme:themed?.theme||'fantasy',offhandKind,
  weaponCategory,weaponIconRow,weaponIconCol,weaponIconPath:weaponIconPathValue,
  armorCategory:slot==='chest'?armorRows[armorIconRow]?.category:null,armorIconRow,armorIconCol,armorIconPath:armorIconPathValue,
  flavor:slot==='weapon'?`${weaponCategory}. Imagen individual: ${weaponIconPathValue}. La progresión por fila respeta rareza y nivel.`:slot==='chest'?`${armorRows[armorIconRow]?.category}. Imagen individual: ${armorIconPathValue}. La progresión por fila va de menos a más poder.`:(themed?.flavor||'Un objeto con más historia de la que conviene preguntar.'),
  defenseStat:slot==='weapon'?(weaponCategoryStats[weaponCategory]||'strength'):inferWeaponDefenseStat({name:themed?.name||'',iconShape,theme:themed?.theme||'fantasy'}),
  rangeMin:slot==='weapon'?weaponRangeBounds({weaponCategory,name:weaponNameForCategory(weaponCategory,weaponIconCol)}).min:null,
  rangeMax:slot==='weapon'?weaponRangeBounds({weaponCategory,name:weaponNameForCategory(weaponCategory,weaponIconCol)}).max:null,
  affixes,passives,effects,
  desc:`Nivel ${itemLevel} · Poder ${score}`
 });
}
function log(msg,cls=''){const d=document.createElement('div');d.className=cls;d.textContent=msg;document.getElementById('log').prepend(d);if(game?.multiplayer&&game.mpCapture&&cls&&cls!=='sys')game.mpPendingEvents=(game.mpPendingEvents||[]).concat({m:msg,c:cls}).slice(-8)}
// ---- In-page confirm / alert / prompt --------------------------------------
// The browser's native confirm()/alert()/prompt() are drawn OUTSIDE the page
// by the browser itself, so nothing in this codebase - keyboard handlers,
// and above all the gamepad navigation in joystick.js - can focus or press
// their buttons. Playing with a pad used to dead-end on every "¿Confirmas
// +1 a Fuerza?" at level up. These three drop-in replacements render the
// same question as a normal in-page modal (#uiPromptModal), so the regular
// gamepad/keyboard focus machinery drives them like any other menu.
//
// Differences from the natives, and why they are safe:
//  - uiConfirm/uiTextPrompt return a Promise, so their call sites became
//    `await uiConfirm(...)` inside async handlers (event handlers ignore the
//    returned promise).
//  - uiAlert does NOT block; every call site only ever showed a message and
//    returned, so nothing depended on the pause.
//  - Only one dialog can be open at a time: opening a second one resolves
//    the first as cancelled instead of stacking (matches native behaviour
//    closely enough, and can only happen from unrelated async paths).
let uiPromptResolve=null;
function uiPromptClose(value){
 const modal=document.getElementById('uiPromptModal');
 modal?.classList.remove('open');
 const resolve=uiPromptResolve;uiPromptResolve=null;
 if(resolve)resolve(value);
}
function uiPromptOpen({title,message,accept,cancel,input}){
 const modal=document.getElementById('uiPromptModal');
 // No modal in the DOM (should not happen, but never strand the caller):
 // fall back to the native dialogs rather than hanging on a promise that
 // can never resolve.
 if(!modal)return Promise.resolve(input!=null?window.prompt(message,input):cancel?window.confirm(message):(window.alert(message),true));
 if(uiPromptResolve)uiPromptClose(input!=null?null:false);
 document.getElementById('uiPromptTitle').textContent=title;
 const text=document.getElementById('uiPromptText');text.className='small uiPromptText';text.textContent=message;
 const field=document.getElementById('uiPromptField'),inputEl=document.getElementById('uiPromptInput');
 field.classList.toggle('hidden',input==null);
 inputEl.value=input==null?'':String(input);
 const acceptBtn=document.getElementById('uiPromptAccept'),cancelBtn=document.getElementById('uiPromptCancel');
 acceptBtn.textContent=accept;
 cancelBtn.textContent=cancel||'';
 cancelBtn.classList.toggle('hidden',!cancel);
 modal.classList.add('open');
 const promise=new Promise(resolve=>{uiPromptResolve=resolve});
 // Re-focus for the gamepad: the text field when there is one, otherwise
 // the accept button, so A/✕ confirms straight away.
 setTimeout(()=>{if(typeof focusGamepadElement==='function')focusGamepadElement(input==null?acceptBtn:inputEl)},0);
 return promise;
}
function uiConfirm(message,title='CONFIRMAR',accept='ACEPTAR',cancel='CANCELAR'){return uiPromptOpen({title,message,accept,cancel})}
function uiAlert(message,title='AVISO'){return uiPromptOpen({title,message,accept:'ACEPTAR',cancel:''})}
function uiTextPrompt(message,defaultValue='',title='ESCRIBE UN NOMBRE'){return uiPromptOpen({title,message,accept:'ACEPTAR',cancel:'CANCELAR',input:defaultValue})}
document.getElementById('uiPromptAccept')?.addEventListener('click',()=>{
 const field=document.getElementById('uiPromptField');
 uiPromptClose(field.classList.contains('hidden')?true:document.getElementById('uiPromptInput').value);
});
document.getElementById('uiPromptCancel')?.addEventListener('click',()=>{
 const field=document.getElementById('uiPromptField');
 uiPromptClose(field.classList.contains('hidden')?false:null);
});
document.getElementById('uiPromptInput')?.addEventListener('keydown',e=>{
 if(e.key==='Enter'){e.preventDefault();uiPromptClose(e.target.value)}
 else if(e.key==='Escape'){e.preventDefault();uiPromptClose(null)}
});
function banner(text){const d=document.createElement('div');d.className='banner';d.textContent=text;document.body.appendChild(d);setTimeout(()=>d.remove(),2100)}
function mapDimensions(){return{rows:game?.map?.length||ROWS,cols:game?.map?.[0]?.length||COLS}}
function camera(){const{rows,cols}=mapDimensions();return{x:Math.max(0,Math.min(Math.max(0,cols-visibleTiles),game.player.x-Math.floor(visibleTiles/2))),y:Math.max(0,Math.min(Math.max(0,rows-visibleTiles),game.player.y-Math.floor(visibleTiles/2)))}}
function floating(text,x,y,color='#fff'){const r=canvas.getBoundingClientRect(),c=camera(),d=document.createElement('div');d.className='floatText';d.textContent=text;d.style.color=color;d.style.left=`${r.left+(x-c.x+.45)*r.width/visibleTiles}px`;d.style.top=`${r.top+(y-c.y+.25)*r.height/visibleTiles}px`;document.body.appendChild(d);setTimeout(()=>d.remove(),850)}
// GSAP effects are independent DOM particles: they keep canvas art crisp and
// avoid spritesheets while still covering movement, attacks and every skill component.
