 if(w.damageDice)return w.damageDice;
 if(r>=9)return'1d10';
 if(r>=7)return'1d8+1';
 if(r>=3)return'1d8';
 const text=`${w.name||''} ${w.iconShape||''}`.toLowerCase();
 if(/(martillo|hammer|hacha|axe|maza|mace)/.test(text))return'1d10';
 if(/(espada|sword|blade)/.test(text))return'1d8';
