  if(configWorldObjectRows[objectKey]?.icon===undefined){if(st)st.textContent='Cargando asset...';await fetchConfigWorldObjectDetail(objectKey)}
 const asset=listConfigAssets().find(a=>a.key===objectKey);if(!asset)return;
