let configDungeonWorlds=[],editingDungeonWorldId=null,editingDungeonBaseline=null,dungeonPreviewWorld=null,dungeonPreviewFloor=0,importedDungeonDraft=false;
const dungeonField=id=>document.getElementById(id);
function dungeonFloorDrafts(){return [...document.querySelectorAll('[data-dungeon-floor]')].map((row,i)=>({floor:i+1,archetype:row.querySelector('[data-dungeon-archetype]').value,story:row.querySelector('[data-dungeon-story]').value.trim(),floorId:row.querySelector('[data-dungeon-floor-type]').value}))}
function renderDungeonFloorEditor(plan=[]){const root=dungeonField('dungeonFloorEditor');if(!root)return;const floors=normalizedConfigFloors(),arch=Object.entries(FLOOR_ARCHETYPES).map(([id,a])=>`<option value="${id}">${a.label||id}</option>`).join('');root.innerHTML=Array.from({length:DUNGEON_FLOORS},(_,i)=>{const row=plan[i]||{};return `<div class="configItem dungeonFloorRow" data-dungeon-floor="${i+1}"><b>${i+1}</b><div class="dungeonFloorControls"><label>Tipo de piso<select data-dungeon-archetype><option value="">Aleatorio</option>${arch}<option value="megaboss">Megaboss</option></select></label><label>Tileset<select data-dungeon-floor-type><option value="">Aleatorio</option>${floors.map(f=>`<option value="${f.dbId||f.id||f.name}">${f.name}</option>`).join('')}</select></label><label>Historia del piso<input data-dungeon-story maxlength="240" placeholder="Narrativa al entrar..."></label></div></div>`}).join('');[...root.querySelectorAll('[data-dungeon-floor]')].forEach((el,i)=>{const row=plan[i]||{};el.querySelector('[data-dungeon-archetype]').value=row.archetype||'';el.querySelector('[data-dungeon-floor-type]').value=row.floorId||'';el.querySelector('[data-dungeon-story]').value=row.story||''})}
function dungeonConfigParams(){const fine={story:dungeonField('dungeonConfigStory').value.trim(),lootPerFloor:Number(dungeonField('dungeonLootPerFloor').value)||0,width:Number(dungeonField('dungeonWidth').value)||49,height:Number(dungeonField('dungeonHeight').value)||49,geometry:dungeonField('dungeonGeometry').value,roomDensityPct:Number(dungeonField('dungeonRoomDensity').value)||100};const floorPlan=dungeonFloorDrafts();return normalizeWorldParams({damageReceivedPct:dungeonField('dungeonDamageReceived').value,damageDealtPct:dungeonField('dungeonDamageDealt').value,lifePct:dungeonField('dungeonLife').value,xpReceivedPct:dungeonField('dungeonXp').value,enemyCountPct:dungeonField('dungeonEnemyCount').value,enemyLootPct:dungeonField('dungeonEnemyLoot').value,apMode:dungeonField('dungeonApMode').checked,floorPlan,fine})}
function dungeonChangedLeaves(previous,next){
 const changes=[],walk=(before,after,path)=>{
  if(Array.isArray(after)){if(JSON.stringify(before)!==JSON.stringify(after))changes.push({path,value:after});return}
  if(after&&typeof after==='object'){for(const key of Object.keys(after))walk(before?.[key],after[key],[...path,key]);return}
  if(before!==after)changes.push({path,value:after});
 };
 walk(previous,next,['params']);return changes
}
function resetDungeonConfig(){editingDungeonWorldId=null;editingDungeonBaseline=null;importedDungeonDraft=false;dungeonField('dungeonConfigName').value='';dungeonField('dungeonConfigStory').value='';for(const [id,v] of [['dungeonDamageReceived',125],['dungeonDamageDealt',100],['dungeonLife',125],['dungeonXp',100],['dungeonEnemyCount',100],['dungeonEnemyLoot',100],['dungeonLootPerFloor',4],['dungeonWidth',49],['dungeonHeight',49],['dungeonRoomDensity',100]])dungeonField(id).value=v;dungeonField('dungeonGeometry').value='rooms';dungeonField('dungeonApMode').checked=false;renderDungeonFloorEditor();dungeonPreviewWorld=null;drawDungeonGeometryPreview();dungeonField('dungeonConfigStatus').textContent='Nueva dungeon.'}
function fillDungeonConfig(world,{imported=false}={}){editingDungeonWorldId=imported?null:(world.id||null);importedDungeonDraft=imported;const p=normalizeWorldParams(world.world_json?.params||world.params),fine=p.fine||world.world_json?.fine||{};editingDungeonBaseline=JSON.parse(JSON.stringify(p));dungeonField('dungeonConfigName').value=world.world_name||world.worldName||'';dungeonField('dungeonConfigStory').value=fine.story||world.world_json?.story||'';for(const [id,key] of [['dungeonDamageReceived','damageReceivedPct'],['dungeonDamageDealt','damageDealtPct'],['dungeonLife','lifePct'],['dungeonXp','xpReceivedPct'],['dungeonEnemyCount','enemyCountPct'],['dungeonEnemyLoot','enemyLootPct']])dungeonField(id).value=p[key];dungeonField('dungeonLootPerFloor').value=fine.lootPerFloor??4;dungeonField('dungeonWidth').value=fine.width??49;dungeonField('dungeonHeight').value=fine.height??49;dungeonField('dungeonGeometry').value=fine.geometry||'rooms';dungeonField('dungeonRoomDensity').value=fine.roomDensityPct??100;dungeonField('dungeonApMode').checked=!!p.apMode;const plans=p.floorPlan||[];renderDungeonFloorEditor(plans.map((r,i)=>({...r,story:r.story||world.world_json?.floors?.[i]?.story||'',archetype:r.archetype||world.world_json?.floors?.[i]?.archetype||''})));dungeonPreviewWorld=world.world_json||world;dungeonPreviewFloor=0;drawDungeonGeometryPreview();dungeonField('dungeonConfigStatus').textContent=`Editando #${world.id||'importada'}.`}
async function fetchConfigDungeons(){const list=dungeonField('dungeonConfigList'),status=dungeonField('dungeonConfigStatus');if(!list)return;try{const r=await fetch('/api/dungeon-worlds?light=1'),data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudieron cargar');configDungeonWorlds=Array.isArray(data)?data:[];list.innerHTML=configDungeonWorlds.length?configDungeonWorlds.map(w=>`<div class="configItem"><span>⌂</span><div><b>${w.world_name||'Sin nombre'}</b><span class="small">#${w.id} · ${new Date(w.created_at).toLocaleString()}</span><div class="configItemActions"><button data-dungeon-edit="${w.id}">Editar</button><button data-dungeon-export="${w.id}">Exportar</button></div></div></div>`).join(''):'<p class="small">No hay dungeons guardadas.</p>';list.querySelectorAll('[data-dungeon-edit]').forEach(b=>b.onclick=()=>loadConfigDungeon(b.dataset.dungeonEdit));list.querySelectorAll('[data-dungeon-export]').forEach(b=>b.onclick=()=>exportStoredDungeon(b.dataset.dungeonExport))}catch(e){status.textContent=e.message}}
async function loadConfigDungeon(id){const r=await fetch(`/api/dungeon-worlds?id=${encodeURIComponent(id)}`),world=await r.json();if(!r.ok)throw new Error(world.error||'No se pudo cargar');fillDungeonConfig(world)}
function downloadDungeonJson(data,name='dungeon'){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name.replace(/[^a-z0-9_-]+/gi,'-')}.json`;a.click();URL.revokeObjectURL(a.href)}
async function exportStoredDungeon(id){const r=await fetch(`/api/dungeon-worlds?id=${encodeURIComponent(id)}`),w=await r.json();if(r.ok)downloadDungeonJson(w,w.world_name||'dungeon')}
function drawDungeonGeometryPreview(){const c=dungeonField('dungeonGeometryPreview');if(!c)return;const q=c.getContext('2d'),floors=dungeonPreviewWorld?.floors||[],f=floors[dungeonPreviewFloor];q.fillStyle='#09070c';q.fillRect(0,0,c.width,c.height);dungeonField('dungeonPreviewLabel').textContent=`Piso ${dungeonPreviewFloor+1} / ${Math.max(1,floors.length)}${f?.archetypeLabel?' · '+f.archetypeLabel:''}`;if(!f?.map){q.fillStyle='#aa9ab2';q.font='16px monospace';q.fillText('Guarda o importa para generar la vista previa',35,260);return}const h=f.map.length,w=Math.max(...f.map.map(r=>r.length)),sz=Math.min(c.width/w,c.height/h),ox=(c.width-w*sz)/2,oy=(c.height-h*sz)/2;f.map.forEach((row,y)=>row.forEach((v,x)=>{q.fillStyle=v===1?'#241a2c':v===2?'#a26d3d':v===3?'#ffc35a':'#334735';q.fillRect(ox+x*sz,oy+y*sz,Math.ceil(sz),Math.ceil(sz))}));for(const r of f.rooms||[]){q.strokeStyle='#6ed4c5';q.strokeRect(ox+r.x*sz,oy+r.y*sz,r.w*sz,r.h*sz)}for(const e of f.enemies||[]){q.fillStyle=e.boss?'#ff4d4d':'#df7a65';q.fillRect(ox+e.x*sz,oy+e.y*sz,Math.max(2,sz),Math.max(2,sz))}for(const x of f.chests||[]){q.fillStyle='#ffd068';q.fillRect(ox+x.x*sz,oy+x.y*sz,Math.max(2,sz),Math.max(2,sz))}if(f.spawn){q.fillStyle='#72e5ff';q.fillRect(ox+f.spawn.x*sz,oy+f.spawn.y*sz,Math.max(3,sz),Math.max(3,sz))}if(f.stairs){q.fillStyle='#fff';q.fillRect(ox+f.stairs.x*sz,oy+f.stairs.y*sz,Math.max(3,sz),Math.max(3,sz))}}
async function saveDungeonConfig(){
 const status=dungeonField('dungeonConfigStatus'),name=dungeonField('dungeonConfigName').value.trim()||'Dungeon sin nombre';
 try{
  const params=dungeonConfigParams();
  if(editingDungeonWorldId){
   const changes=dungeonChangedLeaves(editingDungeonBaseline||{},params),originalName=configDungeonWorlds.find(w=>String(w.id)===String(editingDungeonWorldId))?.world_name;
   if(!changes.length&&name===originalName){status.textContent='No hay parámetros modificados.';return}
   status.textContent=`Guardando ${changes.length} parámetro(s) modificado(s), sin transferir mapas ni el JSON completo...`;
   const r=await fetch('/api/dungeon-worlds',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:editingDungeonWorldId,world_name:name!==originalName?name:null,changes})}),data=await r.json();
   if(!r.ok)throw new Error(data.error||data.message||'No se pudo actualizar');
   editingDungeonBaseline=JSON.parse(JSON.stringify(params));
   // Keep the already loaded preview locally; only its lightweight params
   // change. Pregenerated maps are intentionally untouched by an edit.
   if(dungeonPreviewWorld)dungeonPreviewWorld.params=params;
   await fetchConfigDungeons();status.textContent='Parámetros modificados consolidados; la geometría pregenerada no se reinsertó.';return
  }
  status.textContent=importedDungeonDraft?'Consolidando la dungeon importada...':'Generando los 6 pisos y su geometría para la nueva dungeon...';
  if(!importedDungeonDraft){if(!configFloors.length)await fetchConfigFloors();if(!configEnemyFamilies.length)await fetchEnemyConfig()}
  const world=importedDungeonDraft?structuredClone(dungeonPreviewWorld):createDungeonWorldJson(name,params);world.params=params;world.worldName=name;world.appVersion=APP_VERSION;world.story=params.fine.story;world.fine=params.fine;(world.floors||[]).forEach((f,i)=>f.story=params.floorPlan[i]?.story||f.story||'');
  const r=await fetch('/api/dungeon-worlds',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({world_name:name,world_json:world})}),data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo guardar');
  editingDungeonWorldId=data.id;editingDungeonBaseline=JSON.parse(JSON.stringify(params));importedDungeonDraft=false;dungeonPreviewWorld=world;dungeonPreviewFloor=0;drawDungeonGeometryPreview();await fetchConfigDungeons();status.textContent='Dungeon nueva consolidada y vista previa actualizada.'
 }catch(e){status.textContent=`Error: ${e.message}`}
}
function setupDungeonConfigMode(){if(dungeonField('dungeonFloorEditor')?.dataset.ready)return;dungeonField('dungeonFloorEditor').dataset.ready='1';renderDungeonFloorEditor();dungeonField('saveDungeonConfigBtn').onclick=saveDungeonConfig;dungeonField('newDungeonConfigBtn').onclick=resetDungeonConfig;dungeonField('deleteDungeonConfigBtn').onclick=async()=>{if(!editingDungeonWorldId||!await uiConfirm('¿Borrar esta dungeon definitivamente?'))return;const r=await fetch(`/api/dungeon-worlds?id=${encodeURIComponent(editingDungeonWorldId)}`,{method:'DELETE'});if(r.ok){resetDungeonConfig();fetchConfigDungeons()}};dungeonField('exportDungeonConfigBtn').onclick=()=>downloadDungeonJson({world_name:dungeonField('dungeonConfigName').value,world_json:dungeonPreviewWorld||{params:dungeonConfigParams()}},dungeonField('dungeonConfigName').value||'dungeon');dungeonField('importDungeonConfigInput').onchange=async e=>{try{const raw=JSON.parse(await e.target.files[0].text());fillDungeonConfig(raw.world_json?raw:{world_json:raw.dungeon||raw.world||raw,world_name:raw.worldName||raw.world_name||raw.name},{imported:true})}catch(err){dungeonField('dungeonConfigStatus').textContent=`JSON inválido: ${err.message}`}e.target.value=''};dungeonField('dungeonPreviewPrev').onclick=()=>{dungeonPreviewFloor=Math.max(0,dungeonPreviewFloor-1);drawDungeonGeometryPreview()};dungeonField('dungeonPreviewNext').onclick=()=>{dungeonPreviewFloor=Math.min((dungeonPreviewWorld?.floors?.length||1)-1,dungeonPreviewFloor+1);drawDungeonGeometryPreview()};fetchConfigDungeons();drawDungeonGeometryPreview()}

async function fetchDungeonWorlds(){
 const status=document.getElementById('worldStatus'),list=document.getElementById('worldList');if(!status||!list)return;
 status.textContent='Cargando dungeons desde Supabase...';list.innerHTML='';
 try{const r=await fetch('/api/dungeon-worlds?light=1');const data=await r.json();if(!r.ok)throw new Error(data.error||data.message||'No se pudieron cargar las dungeons');
  if(!data.length){status.textContent='No hay dungeons guardadas. Crea una nueva.';return}
  status.textContent=`${data.length} dungeon(s) disponibles.`;
  list.innerHTML=data.map(w=>`<button type="button" class="worldCard" data-world-id="${w.id}"><b>${w.world_name||'Dungeon sin nombre'}</b><span>#${w.id} · ${new Date(w.created_at).toLocaleString()}</span></button>`).join('');
  list.querySelectorAll('[data-world-id]').forEach(btn=>btn.onclick=async()=>{
   btn.disabled=true;status.textContent='Cargando dungeon seleccionada...';
   try{
    const wr=await fetch(`/api/dungeon-worlds?id=${encodeURIComponent(btn.dataset.worldId)}`);
    const world=await wr.json();
    if(!wr.ok)throw new Error(world.error||world.message||'No se pudo cargar la dungeon');
    if(!world)throw new Error('La dungeon ya no existe.');
    selectedDungeonWorld=world;proceedAfterWorldChosen();
   }catch(e){status.textContent=`Error cargando dungeon_world: ${e.message}`;btn.disabled=false}
  });
 }catch(e){status.textContent=`Error cargando dungeon_world: ${e.message}`}
}
async function createDungeonWorld(){
 const btn=document.getElementById('createWorldBtn'),status=document.getElementById('worldStatus'),name=(document.getElementById('worldNameInput')?.value||'Dungeon sin nombre').trim(),params=readWorldParamsForm();
 btn.disabled=true;status.textContent='Cargando floors y familias desde Supabase...';
 try{await ensureConfigFloorsHydrated();await fetchEnemyConfig({throwOnError:true});await ensureConfigItemsHydrated();if(!configChests.length)await fetchConfigChests();if(!normalizedEnemyFamilies().length)throw new Error('Debes consolidar al menos una familia con enemigos en enemy_family y enemy_detail antes de crear una dungeon.');if(!normalizedSupabaseFloors().length)throw new Error('Debes consolidar al menos un floor en config_floor antes de crear una dungeon.');const world_json=createDungeonWorldJson(name,params);const r=await fetch('/api/dungeon-worlds',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({world_name:name,world_json})});const text=await r.text();let data;try{data=JSON.parse(text)}catch(e){throw new Error(text||'Respuesta no JSON al crear la dungeon')}if(!r.ok)throw new Error(data.error||data.message||'No se pudo crear la dungeon');
  selectedDungeonWorld=data;proceedAfterWorldChosen();
 }catch(e){status.textContent=`Error: ${e.message}`;btn.disabled=false}
}

function sumEquippedItemLevel(equipment){
 if(!equipment)return 0;
 return Object.values(equipment).reduce((sum,item)=>sum+(item?.itemLevel||item?.score||0),0);
}
function computeScore(bundle){
 const player=bundle?.player||{};
 const level=player.level||1;
 const ilvl=sumEquippedItemLevel(player.equipment);
 const maxFloor=bundle?.maxFloorReached||1;
 const gold=player.gold||0;
 return Math.round(level*100+ilvl*5+maxFloor*50+gold/10);
}
function normalizeFeats(raw={}){return {elites:Math.max(0,Number(raw?.elites)||0),bosses:Math.max(0,Number(raw?.bosses)||0),megabosses:Math.max(0,Number(raw?.megabosses)||0),dungeons:Math.max(0,Number(raw?.dungeons)||0)}}
function completeDungeon(){
 if(game.dungeonCompleted)return;
 game.dungeonCompleted=true;game.feats=normalizeFeats(game.feats);game.feats.dungeons++;
 const rarity=topRarityNameForFloor(game.floorEntryLevel||game.player.level);
 const item=makeLoot(game.floorEntryLevel||game.player.level,'dungeonReward',rarity,'equipment');
 if(item){addInventoryItem(item);lootToast(item)}
 const bundle=characterBundleFromGame();
 if(game.pjId)fetch(`/api/user-pj?id=${encodeURIComponent(game.pjId)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({pj_json:bundle,feats:game.feats,pj_score:computeScore(bundle),pj_name:game.player.name,last_use:new Date().toISOString()})}).catch(e=>console.error('No se pudo guardar la dungeon completada',e));
 banner(`DUNGEON COMPLETADA · ${tierDefs[rarity]?.label||rarity}`);log('Dungeon completada: recibes un objeto del tier máximo permitido para tu nivel.','loot');
}
function characterBundleFromGame(){
 return {player:game.player,inventory:game.inventory||[],achievements:game.achievements||{},feats:normalizeFeats(game.feats),bossesKilled:game.bossesKilled||0,chestsOpened:game.chestsOpened||0,maxFloorReached:Math.max(game.maxFloorReached||1,game.floor||1)};
}

async function finishCharacterCreation(){
 const bundle={player:game.player,inventory:game.inventory||[],achievements:game.achievements||{},feats:normalizeFeats(),bossesKilled:0,chestsOpened:0,maxFloorReached:1};
 const score=computeScore(bundle);
 try{
  const r=await fetch('/api/user-pj',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nombre:window.currentUser.nombre,pj_name:bundle.player.name,pj_json:bundle,feats:bundle.feats,pj_status:'alive',pj_score:score,souls:game.player.souls||0,last_use:new Date().toISOString()})});
  const data=await r.json().catch(()=>null);
  // api/user-pj.js forwards Supabase/PostgREST's response verbatim on error,
  // whose shape is {message, details, hint, code} - not {error} - so reading
  // only data.error silently swallowed the real reason and always showed the
  // generic fallback instead. Try every field PostgREST/our own handler
  // actually uses, in order, before giving up on a real message.
  if(!r.ok)throw new Error(data?.error||data?.message||data?.details||data?.hint||`HTTP ${r.status}${r.statusText?' '+r.statusText:''}`);
  // Explicit, blocking confirmation (not just the transient on-canvas banner,
  // which can get lost across this exact screen transition) that the
  // character actually made it into Supabase before we tear down `game` and
  // navigate away - this is the "it looked like it worked but nothing got
  // created" case made impossible to miss.
  uiAlert(`Personaje "${bundle.player.name}" creado y guardado correctamente.`);
  refreshCurrentUserProgress();
 }catch(e){
  console.error('No se pudo guardar el personaje nuevo:',e);
  uiAlert('Error al guardar el personaje: '+e.message);
 }
 game=null;
 startOverlay.classList.add('hidden');
 app.classList.add('hidden');
 openSinglePlayerScreen();
}

